function validate([rewardValues]) {
  if (rewardValues.length < 1 || rewardValues.length > 50000) return 'rewardValues needs 1 to 50000 values.';
  if (rewardValues.some(v => v < 1 || v > 50000)) return 'Each reward is between 1 and 50000.';
  return null;
}

