function maxTotalReward(rewardValues) {
  const values = [...new Set(rewardValues)].sort((a, b) => a - b);
  let reachable = 1n;
  for (const value of values) {
    const shift = BigInt(value);
    const smaller = reachable & ((1n << shift) - 1n);
    reachable |= smaller << shift;
  }
  return reachable.toString(2).length - 1;
}

