function maxTotalReward(rewardValues) {
  // Follow the rules literally: from total x, try every unmarked reward larger than x.
  const marked = rewardValues.map(() => false);
  const explore = x => {
    let best = x;
    for (let i = 0; i < rewardValues.length; i++) {
      if (marked[i] || rewardValues[i] <= x) continue;
      marked[i] = true;
      best = Math.max(best, explore(x + rewardValues[i]));
      marked[i] = false;
    }
    return best;
  };
  return explore(0);
}

