function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 9);
    const top = [3, 10, 30, 50000][Math.floor(rand() * 4)];
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
  }
  const top = 1000 + Math.floor(rand() * 49001);
  const mode = Math.floor(rand() * 3);
  const few = Array.from({ length: 12 }, () => 1 + Math.floor(rand() * top));
  const pick = () => {
    if (mode === 0) return 1 + Math.floor(rand() * top); // anywhere in [1, top]
    if (mode === 1) return top - Math.floor(rand() * (top / 2)); // upper half only
    return few[Math.floor(rand() * few.length)]; // a few values, many repeats
  };
  return [Array.from({ length: 2000 }, pick)];
}
